export const heroById=id=>HEROES.find(h=>h.id===id);
export function heroScaling(wave){return 1+Math.min(1.5,Math.floor(Math.max(0,wave-1)/20)*.08)}
export function unlockHeroes(meta,completedWave){meta.heroesUnlocked??=[];const unlocked=HEROES.filter(h=>completedWave>=h.unlockWave&&!meta.heroesUnlocked.includes(h.id));meta.heroesUnlocked.push(...unlocked.map(h=>h.id));meta.highestCompletedWave=Math.max(meta.highestCompletedWave||0,completedWave);return unlocked}
